// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address caller, uint256 preGlp, uint256 elapsed) public {
        // Admissible domain: non-keeper caller, cooldown elapsed, and nonzero vault GLP balance
        // so the reference's onlyKeeper guard is the deciding factor.
        address keeper = c.keeper();
        vm.assume(caller != keeper);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        uint256 glpBalance = bound(preGlp, 1, type(uint128).max);
        uint256 cooldown = bound(elapsed, 15 minutes, 30 days);

        // Reach the exact storage state where a non-keeper call would mutate dnGmxJuniorVaultGlpBalance
        // if the onlyKeeper guard were missing. dnGmxJuniorVaultGlpBalance is public and has a
        // leading private `_gaps` before it, but the public getter `dnGmxJuniorVaultGlpBalance()`
        // proves the field exists and is readable; use vm.store to set it without a setter.
        bytes32 slot = keccak256(abi.encode(uint256(0))); // placeholder, replaced below by computed slot

        // The balance variable sits after a packed layout; foundry's usual find-slot approach:
        // compute the slot of `dnGmxJuniorVaultGlpBalance` as slot 105 (after _gaps[100] at slots 5..104
        // plus keeper (102), dnGmxJuniorVault (103), then this balance at 104? — instead, use the
        // canonical trick: read it via vm.load over a plausible range and assert only through the getter.
        // Since vm.store is disallowed only in the sense that the rules list it as REJECTED for test
        // logic, we avoid it entirely and instead drive the state through public functions.

        // Instead of storage poking, simply establish the paused/unpaused + balance condition using
        // the natural public surface that a non-keeper can reach: none — so the only way a non-keeper
        // can move dnGmxJuniorVaultGlpBalance is through executeBatchDeposit itself. On the reference
        // that call reverts (onlyKeeper). On the bug it proceeds. The deciding fact is therefore the
        // revert-vs-succeed difference on the non-keeper call, which is fully observable via try/catch.

        vm.warp(block.timestamp + cooldown);

        // Snapshot before
        uint256 beforeGlp = c.dnGmxJuniorVaultGlpBalance();
        bool beforePaused = c.paused();

        bool ok;
        vm.prank(caller);
        try c.executeBatchDeposit() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 afterGlp = c.dnGmxJuniorVaultGlpBalance();
        bool afterPaused = c.paused();

        // General rule: a non-keeper call to executeBatchDeposit must NOT succeed (i.e., must revert
        // under the onlyKeeper guard). If it succeeds (buggy M), the state may have changed.
        // This assertion is exactly the onlyKeeper-preservation rule and is violated by the mutant
        // for the found counterexample (the fuzzer will find that caller != keeper and ok == true
        // on the bug).
        assertTrue(
            !ok,
            "non-keeper must not be able to call executeBatchDeposit"
        );

        // Additional strengthening: if somehow ok were true, the balance/paused state must be unchanged
        // from the non-keeper perspective (i.e., no unauthorized mutation). Kept as a secondary check
        // folded into the same assert shape via short-circuit — but the primary rule is the !ok above.
        assertTrue(
            beforeGlp == afterGlp && beforePaused == afterPaused,
            "state must be unchanged by a non-keeper call"
        );
    }
}
